action.code:
if (polygon.size() < 3) {
    return true;
}

// A polygon is convex if it is either strongly CCW convex or strongly CW convex.
// Using CGAL's provided utility functions from convexity_check_2.h
if (CGAL::is_ccw_strongly_convex_2(polygon.begin(), polygon.end())) {
    return true;
}
if (CGAL::is_cw_strongly_convex_2(polygon.begin(), polygon.end())) {
    return true;
}

return false;

